//! INPUT autocomplete metadata uses the shared HTML autofill grammar.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form autocomplete=off><input id=area name=q value=Seed><input id=hidden name=anchor type=hidden value=Anchor><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://input-autocomplete.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_autocomplete_canonical_accessor_once_dom_string_and_raw_content(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'autocomplete');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get autocomplete'||a.set.name!=='set autocomplete'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'autocomplete')||x.autocomplete!=='')throw 'canonical autocomplete';var calls=0;x.autocomplete={toString:function(){calls++;return '  ON  ';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.autocomplete!=='on'||x.getAttributeNS(null,'autocomplete')!=='  ON  '||x.value!=='Seed')throw 'processed getter exact authored content';");}
#[test]
fn input_autocomplete_processed_tokens_contact_scope_credential_and_invalid_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');for(var pair of [['off','off'],['NAME','name'],['  section-CHECKOUT  shipping work EMAIL webauthn ','section-checkout shipping work email webauthn'],['home tel','home tel'],['shipping street-address','shipping street-address'],['webauthn','webauthn'],['call-sign',''],['name extra',''],['home name',''],['shipping off',''],['work shipping email',''],['section-x section-y name',''],['','']]){x.setAttribute('autocomplete',pair[0]);if(x.autocomplete!==pair[1]||x.getAttributeNS(null,'autocomplete')!==pair[0])throw 'autofill processing grammar';}if(x.value!=='Seed')throw 'metadata filled native value';");}
#[test]
fn input_autocomplete_inert_exact_names_and_raw_section_identifier(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','input');x.setAttributeNS('urn:other','autocomplete','off');x.setAttributeNS(null,'AUTOCOMPLETE','off');if(x.autocomplete!=='')throw 'namespace alias';x.autocomplete=' SECTION-X\ud800 SHIPPING EMAIL ';if(x.autocomplete!=='section-x\ud800 shipping email'||x.getAttributeNS(null,'autocomplete')!==' SECTION-X\ud800 SHIPPING EMAIL '||x.getAttributeNS('urn:other','autocomplete')!=='off')throw 'exact raw section processing';"#);}

#[test]
fn input_autocomplete_hidden_anchor_mantle_rejects_on_off_but_keeps_detail_hints(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('hidden');for(var pair of [['on',''],[' OFF ',''],['NAME','name'],['section-X shipping home EMAIL','section-x shipping home email'],['webauthn','webauthn'],['section-x off','']]){x.autocomplete=pair[0];if(x.autocomplete!==pair[1]||x.getAttributeNS(null,'autocomplete')!==pair[0]||x.value!=='Anchor')throw 'anchor mantle';}");}

#[test]
fn input_autocomplete_field_categories_case_and_infra_whitespace(){let(mut d,mut f,mut p)=fixture();for field in "name honorific-prefix given-name additional-name family-name honorific-suffix nickname organization-title username new-password current-password one-time-code organization street-address address-line1 address-line2 address-line3 address-level4 address-level3 address-level2 address-level1 country country-name postal-code cc-name cc-given-name cc-additional-name cc-family-name cc-number cc-exp cc-exp-month cc-exp-year cc-csc cc-type transaction-currency transaction-amount language bday bday-day bday-month bday-year sex url photo tel tel-country-code tel-national tel-area-code tel-local tel-local-prefix tel-local-suffix tel-extension email impp".split(' '){p.begin_job();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.autocomplete='SECTION-A BILLING {} WEBAUTHN';if(x.autocomplete!=='section-a billing {field} webauthn')throw 'field category';",field.to_ascii_uppercase()));}run(&mut d,&mut f,&mut p,r#"for(var pair of [['\tHOME\nTEL\r\f','home tel'],['section- name','section- name'],['SECTION-É shipping email','section-É shipping email'],['\u00a0name',''],['name\u000b',''],['section-x home email','section-x home email'],['section-x work name',''],['shipping home email webauthn','shipping home email webauthn'],['section-x shipping home email webauthn extra',''],['on webauthn',''],['section-x webauthn',''],['home webauthn',''],['section-x shipping fax impp webauthn','section-x shipping fax impp webauthn']]){x.autocomplete=pair[0];if(x.autocomplete!==pair[1])throw 'ASCII whitespace and ordering';}"#);}
#[test]
fn input_autocomplete_authority_brands_and_abrupt_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),P=HTMLInputElement.prototype,a=Object.getOwnPropertyDescriptor(P,'autocomplete'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'on';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.autocomplete={toString:function(){calls++;x.autocomplete='off';return ' EMAIL ';}};if(calls!==1||x.autocomplete!=='email')throw 'outer conversion';var marker={};try{x.autocomplete={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.autocomplete!=='email'||x.getAttribute('data-side')!=='kept')throw 'abrupt state';Object.defineProperty(P,'autocomplete',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.autocomplete='override';a.set.call(x,'ON');if(x.autocomplete!=='author'||a.get.call(x)!=='on')throw 'saved authority';delete P.autocomplete;if(x.autocomplete!==undefined)throw 'hidden member';Object.defineProperty(P,'autocomplete',a);var C=HTMLInputElement;delete window.HTMLInputElement;if(!(x instanceof C)||a.get.call(x)!=='on')throw 'saved constructor';");}
#[test]
fn input_autocomplete_resource_refusal_preserves_dom_native_state_and_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.autocomplete='section-x shipping home email webauthn';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("textarea")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.input_autocomplete_get(object).map(|_|())}else{bridge.input_autocomplete_set(object,&Value::String("section-growing-growing-growing-growing-growing shipping home email webauthn".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.autocomplete='ON';if(x.autocomplete!=='on'||x.value!=='Seed')throw 'fresh recovery';");}}}

#[test]
fn input_autocomplete_attribute_producers_observation_and_dirty_editor_are_independent(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='Edited';x.autocomplete='off';var attribute=x.getAttributeNodeNS(null,'autocomplete'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['autocomplete']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('autocomplete',' EMAIL ');","x.setAttributeNS(null,'autocomplete',' EMAIL ');","attribute.value=' EMAIL ';","attribute.nodeValue=' EMAIL ';","attribute.textContent=' EMAIL ';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.autocomplete!=='email'||x.getAttributeNodeNS(null,'autocomplete')!==attribute||records.length!==1||records[0].attributeName!=='autocomplete'||x.value!=='Edited')throw 'actual attribute integration';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute('autocomplete');replacement.value='HOME TEL';x.setAttributeNodeNS(replacement);if(x.autocomplete!=='home tel'||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'attribute replacement';x.removeAttribute('autocomplete');if(x.autocomplete!=='')throw 'missing default';");}
#[test]
fn input_autocomplete_inert_type_namespace_state_and_independent_raw_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','input');x.setAttributeNS('urn:foreign','type','hidden');x.setAttributeNS(null,'TYPE','hidden');x.autocomplete='OFF';if(x.autocomplete!=='off')throw 'type namespace alias';x.setAttributeNS(null,'type','HiDdEn');if(x.autocomplete!=='')throw 'hidden case state';x.setAttributeNS(null,'type','hidden ');if(x.autocomplete!=='off')throw 'type keyword must not trim';x.setAttributeNS(null,'type','hidden');x.autocomplete=' SECTION-X\ud800 HOME EMAIL ';var copy=x.cloneNode(false);copy.autocomplete='on';if(x.autocomplete!=='section-x\ud800 home email'||copy.autocomplete!==''||copy.getAttributeNS(null,'autocomplete')!=='on'||copy.getAttributeNodeNS(null,'autocomplete')===x.getAttributeNodeNS(null,'autocomplete'))throw 'independent anchor copy';x.autocomplete='em\ud800ail';if(x.autocomplete!==''||x.autocomplete)throw 'invalid empty';"#);}
#[test]
fn input_autocomplete_native_input_state_matrix_preserves_values_checked_and_editors(){for kind in ["hidden","text","search","tel","url","email","password","date","month","week","time","datetime-local","number","range","color","checkbox","radio","file","submit","image","reset","button"]{let html=format!("<html><body><form autocomplete=off><input id=area type='{kind}' name=q value=Seed checked></form></body></html>");let mut d=crate::html::parse(&html);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://input-autocomplete.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let n=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("area")).unwrap();let snapshot=|f:&Forms|f.controls.get(&n).map(|c|(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.checked,c.dirty_checked,c.dirty_value,c.name.clone(),c.caption.clone()));let before=snapshot(&f);run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.autocomplete='ON';if(x.autocomplete!=='{}')throw 'state mantle';x.autocomplete='SECTION-X EMAIL';if(x.autocomplete!=='section-x email')throw 'state detail hint';",if kind=="hidden"{""}else{"on"}));assert_eq!(snapshot(&f),before,"{kind}");}}
#[test]
fn input_autocomplete_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'autocomplete'),calls=0;if(a.get.call(x)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-input-autocomplete.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://input-autocomplete.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.autocomplete!=='on')throw 'fresh recovery';");}
